INSERT INTO feature VALUES('package-signature','modules','An import at a signature','packages','implemented','ordinary',NULL,'`import <address> : S ;` writes the theory an importer reads its source at. The source''s interface is its `pub` declarations, each at the type it is written at, inferred and never stated. Each operation and constant of `S`''s model signature names a `pub` declaration of the source whose written type is the member''s derived type: a signature naming fewer members than the source exports settles, and the import binds the signature''s members and no other, qualified or not. A member the source exports no `pub` declaration of is refused `SignatureMismatch.Missing`, one it exports at another type `SignatureMismatch.Sort`, and one the match reads no type for, a declaration with no signature or a sort, a law or a nested model of `S`, `SignatureMismatch.Unstated`; each refuses every declaration of the importing source at the signature, naming the member.','surface-grammar surface-lowering','corpus/ledger/features/package-signature.gandr corpus/model/projects/tools/package.gandr corpus/ledger/diagnostics/SignatureMismatch.Missing.gandr corpus/ledger/diagnostics/SignatureMismatch.Sort.gandr corpus/ledger/diagnostics/SignatureMismatch.Unstated.gandr crates/surface-lowering/tests/namespace.rs::an_import_at_a_narrower_signature_settles_3098 crates/surface-lowering/tests/namespace.rs::an_import_at_a_wider_signature_refuses_its_source_3098','corpus/ledger/features/package-signature.gandr',NULL);
